import json, subprocess, sys
GATE = '/workspace/submission/gateway.py'
DIR = {'sip:a@x.test': ['tel:+15550001', 'sip:al@x.test'],
       'sip:b@y.test': ['tel:+15550002'],
       'sip:c@z.test': ['sip:c2@z.test']}
ACC = {'s1': {'primary': 'sip:a@x.test', 'allow': ['sip:b@y.test']},
       's2': {'primary': 'sip:c@z.test', 'allow': []}}
GW = {'edge': {'local_domains': ['x.test', 'y.test'], 'peers': {}},
      'far': {'local_domains': ['x.test'], 'peers': {'edge': ['y.test'], 'ghost': ['z.test']}},
      'any': {'local_domains': ['x.test'], 'peers': {'edge': ['x.test', 'y.test', 'z.test']}},
      'none': {'local_domains': [], 'peers': {}}}
CTX = (DIR, ACC, GW)

def run(batch):
    p = subprocess.run([sys.executable, GATE], input=json.dumps(batch).encode(),
                       stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    if p.returncode != 0:
        raise SystemExit('nonzero exit: %r\n%s' % (p.returncode, p.stderr.decode()[:2000]))
    return json.loads(p.stdout.decode())

def batch(jobs, ctx=CTX):
    directory, accounts, gateways = ctx
    return {'directory': directory, 'accounts': accounts, 'gateways': gateways, 'jobs': jobs}

def job(raw, gateway='edge', kind='local', subject='s1', peer=None, trusted=True, source=None):
    ing = {'kind': kind}
    if kind == 'local':
        ing['subject'] = subject
    elif kind == 'peer':
        ing['name'] = peer
    j = {'gateway': gateway, 'ingress': ing, 'trusted_out': trusted}
    if source is not None:
        j['source'] = source
    elif raw is not None:
        j['raw'] = raw
    return j

def raw(lines, body='hi', method='MESSAGE', uri='sip:b@y.test'):
    if isinstance(lines, str):
        lines = [lines]
    head = ['%s %s SIP/2.0' % (method, uri)]
    if lines:
        head.extend(lines)
    return '\r\n'.join(head) + '\r\n\r\n' + body

BASE = ['From: <sip:a@x.test>;tag=t1', 'To: <sip:b@y.test>', 'Call-ID: c1',
        'CSeq: 1 MESSAGE', 'Content-Length: 2']
def req(lines=(), body='hi', **over):
    d = dict((l.split(':', 1)[0], l.split(':', 1)[1].strip()) for l in BASE)
    d.update(over)
    order = ['From', 'To', 'Call-ID', 'CSeq', 'Content-Length']
    lines = list(lines)
    for k in order:
        if k in d and d[k] is not None:
            lines.append('%s: %s' % (k, d.pop(k)))
    for k, v in d.items():
        if v is not None:
            lines.append('%s: %s' % (k, v))
    return raw(lines, body)

FAILS = []
def check(name, got, want, wire=None):
    ok = True
    if isinstance(want, dict):
        for k, v in want.items():
            if got.get(k) != v:
                ok = False
        if set(got.keys()) != set(want.keys()):
            ok = False
    else:
        ok = got == want
    if not ok:
        FAILS.append(name)
        print('FAIL %-44s got=%s' % (name, json.dumps(got)[:260]))
    else:
        print('ok   %-44s' % name)

def acc(identity='sip:a@x.test', basis='local', private=False):
    return {'status': 'accept', 'identity': identity, 'basis': basis, 'private': private}

def rj(reason):
    return {'status': 'reject', 'reason': reason}

def reasons(jobs, ctx=CTX):
    out = run(batch(jobs, ctx))['results']
    return [x.get('reason') if x['status'] == 'reject' else 'accept' for x in out]
